//! Asking for help, and getting the page the reference would print.
//!
//! `--help` and `-h` are supplied by the parser rather than declared by a CLI, because no spec
//! declares them and one that did would render a `--help` in its own help output. They are
//! recognised after the command's own flags, so a CLI that *does* declare one keeps it.
//!
//! A request comes back as `Error::Help` rather than being printed: a parse that stops to show
//! help has produced no value, which is the shape every caller already handles, and a library
//! that writes to stdout on its own is one an adopter cannot embed. `parse()` — the convenience
//! that reads the process's own arguments — is the one place that prints and exits.

use std::ffi::OsStr;

use usage_argv::Error;
use usage_derive::{Args, Cli, Subcommands};

/// A command with its own flags, to be asked about.
#[derive(Args)]
struct Ls {
    /// Do not print a header
    #[usage(long)]
    no_header: bool,
}

#[derive(Subcommands)]
enum Commands {
    /// List things
    Ls(Box<Ls>),
}

/// A tool whose help is worth asking for
///
/// The long form has this paragraph and the short form does not, which is what gives the two
/// pages something to differ by — the command list no longer does, since a parent says the same
/// thing about a child on either page.
#[derive(Cli)]
#[usage(bin = "ex")]
struct Ex {
    /// Be loud
    #[usage(long, short = 'v')]
    verbose: bool,
    #[usage(subcommand)]
    command: Option<Commands>,
}

#[derive(Debug, Cli)]
#[usage(
    bin = "alternate",
    usage = "Usage: alternate <COMMAND>\n       alternate --version"
)]
struct Alternate {}

#[allow(dead_code)]
#[derive(Args)]
struct RecursiveLeaf {}

#[allow(dead_code)]
#[derive(Subcommands)]
enum RecursiveChildren {
    /// A visible leaf
    Leaf(Box<RecursiveLeaf>),
    /// An internal leaf
    #[usage(hide)]
    Hidden(Box<RecursiveLeaf>),
}

#[allow(dead_code)]
#[derive(Args)]
struct RecursiveParent {
    #[usage(subcommand)]
    command: Option<RecursiveChildren>,
}

#[allow(dead_code)]
#[derive(Subcommands)]
enum RecursiveCommands {
    /// An explicitly early command
    #[usage(display_order = 1)]
    Early,
    /// A visible parent
    Parent(Box<RecursiveParent>),
    /// An unordered command
    Zulu,
}

#[allow(dead_code)]
#[derive(Cli)]
#[usage(bin = "recursive")]
struct Recursive {
    /// Print help for the whole visible command tree
    #[usage(long, global, action = usage_argv::ArgAction::HelpAll)]
    help_all: bool,
    #[usage(subcommand)]
    command: Option<RecursiveCommands>,
}

fn ask(tokens: &[&str]) -> (bool, String) {
    let argv: Vec<&OsStr> = tokens.iter().map(OsStr::new).collect();
    match Ex::parse_from(&argv) {
        Err(Error::Help { cmd, long }) => (
            long,
            usage_argv::help::render(Ex::spec(), cmd, long).expect("the command is this CLI's"),
        ),
        Err(other) => panic!("expected a help request, got {other:?}"),
        Ok(_) => panic!("expected a help request, not a parse"),
    }
}

